"""Expiry handlers (RC seed) — the interesting part is NOT at the top.

The module grows helpers first; the actual lapse handler sits deep in
the file on purpose (deep-file evidence archetype).
"""

import logging

logger = logging.getLogger(__name__)


def _format_order(order_id: str) -> str:
    return f"order:{order_id}"


def _load_order(order_id: str) -> dict:
    return {"id": order_id, "state": "pending"}


def _notify(order_id: str, channel: str) -> None:
    logger.info("notify %s on %s", order_id, channel)


def handle_expiry(order_id: str) -> str:
    """Perform the lapse when the expiry timer fires for a pending order."""
    order = _load_order(order_id)
    if order["state"] != "pending":
        return "ignored"
    _notify(order_id, "email")
    return f"lapsed {_format_order(order_id)}"


def handle_cancellation(order_id: str) -> str:
    """Mark an order cancelled so a later expiry ignores it."""
    return f"cancelled {_format_order(order_id)}"
